    {
      "name": "MvPowerSeries.weightedHomogeneousComponent",
      "module_name": "Mathlib.RingTheory.MvPowerSeries.Order",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_2} → [inst : Semiring R] → (σ → ℕ) → ℕ → MvPowerSeries σ R →ₗ[R] MvPowerSeries σ R"
    },
    {
      "name": "MvPolynomial.weightedTotalDegree",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "definition",
      "type": "{R : Type u_1} →\n  {M : Type u_2} →\n    [inst : CommSemiring R] →\n      {σ : Type u_3} → [AddCommMonoid M] → [inst_2 : SemilatticeSup M] → [OrderBot M] → (σ → M) → MvPolynomial σ R → M"
    },
    {
      "name": "MvPolynomial.coeff_weightedHomogeneousComponent",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M] {w : σ → M} (n : M)\n  (φ : MvPolynomial σ R) [inst_2 : DecidableEq M] (d : σ →₀ ℕ),\n  MvPolynomial.coeff d ((MvPolynomial.weightedHomogeneousComponent w n) φ) =\n    if (Finsupp.weight w) d = n then MvPolynomial.coeff d φ else 0"
    },
    {
      "name": "MvPolynomial.decompose'_apply",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ (R : Type u_1) {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} (w : σ → M) [inst_1 : AddCommMonoid M]\n  [inst_2 : DecidableEq M] (φ : MvPolynomial σ R) (m : M),\n  ↑((MvPolynomial.decompose' R w φ) m) = (MvPolynomial.weightedHomogeneousComponent w m) φ"
    },
    {
      "name": "MvPolynomial.homogeneousComponent",
      "module_name": "Mathlib.RingTheory.MvPolynomial.Homogeneous",
      "kind": "definition",
      "type": "{σ : Type u_1} → {R : Type u_3} → [inst : CommSemiring R] → ℕ → MvPolynomial σ R →ₗ[R] MvPolynomial σ R"
    },
    {
      "name": "MvPolynomial.weightedHomogeneousComponent_apply",
      "module_name": "Mathlib.RingTheory.MvPolynomial.WeightedHomogeneous",
      "kind": "theorem",
      "type": "∀ {R : Type u_1} {M : Type u_2} [inst : CommSemiring R] {σ : Type u_3} [inst_1 : AddCommMonoid M] {w : σ → M} (n : M)\n  (φ : MvPolynomial σ R) [inst_2 : DecidableEq M],\n  (MvPolynomial.weightedHomogeneousComponent w n) φ =\n    ∑ d ∈ φ.support with (Finsupp.weight w) d = n, (MvPolynomial.monomial d) (MvPolynomial.coeff d φ)"
    }
  ]
}
